    <style>
        :root{--navy:#06233d;--deep:#03172b;--teal:#16c7b1;--ink:#12304c;--muted:#7890a8;--line:#dbe8f1}*{box-sizing:border-box}body{margin:0;min-width:320px;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Arial,sans-serif;color:var(--ink);background:#f1f7fb}.admin{min-height:100vh;display:grid;grid-template-columns:205px minmax(0,1fr)}.sidebar{min-height:100vh;padding:15px;color:#d6e3ec;background:radial-gradient(circle at 24% 0,#12647b 0,transparent 31%),linear-gradient(170deg,#093a61,#03192e 76%);display:flex;flex-direction:column}.brand{display:flex;gap:10px;align-items:center;padding:2px 2px 23px;color:#fff}.brand-mark{width:37px;height:37px;display:grid;place-items:center;border-radius:10px;background:linear-gradient(145deg,#1fd7c1,#057d96);box-shadow:0 8px 18px rgba(0,0,0,.15)}.brand-mark:before{content:"⚗";font-size:19px}.brand b{display:block;font-size:15px}.brand small{display:block;margin-top:2px;color:#9db5c8;font-size:8px}.section-label{margin:0 7px 8px;color:#87a5bb;font-size:8px;font-weight:800;letter-spacing:.11em;text-transform:uppercase}.nav{margin-bottom:20px}.nav a{display:flex;align-items:center;gap:11px;min-height:33px;margin:2px 0;padding:8px 10px;color:#bfd0dd;text-decoration:none;border-radius:8px;font-size:10px;font-weight:650;transition:.18s}.nav a:hover,.nav a.active{color:#fff;background:linear-gradient(90deg,#0aa990,#165986);box-shadow:0 7px 16px rgba(0,0,0,.13)}.nav svg{width:16px;height:16px;flex:none;fill:none;stroke:currentColor;stroke-width:1.8}.sidebar-rule{height:1px;margin:0 7px 15px;background:rgba(203,228,242,.12)}.upgrade{margin-top:auto;padding:11px;display:flex;align-items:center;gap:9px;border-radius:9px;color:#d4f7f2;background:linear-gradient(110deg,#087c81,#13536d);font-size:8px}.upgrade-icon{width:27px;height:27px;display:grid;place-items:center;flex:none;border-radius:7px;color:#087e7e;background:#bff7ea;font-size:14px}.upgrade b{display:block;color:#fff;font-size:10px;margin-bottom:2px}.main{min-width:0;padding:0 18px 28px;background:linear-gradient(115deg,#edf7fc 0,#f8fbfd 48%,#edf6fb 100%)}.utility{height:48px;display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 -18px 10px;padding:0 22px;background:#fff;border-bottom:1px solid #e0eaf1;box-shadow:0 2px 8px rgba(16,48,76,.04)}.utility-left,.utility-right{display:flex;align-items:center;gap:13px}.menu-icon{color:#4d6c86;font-size:17px}.search{width:min(280px,32vw);height:29px;display:flex;align-items:center;gap:7px;padding:0 10px;border-radius:7px;color:#88a1b5;background:#f2f7fb;font-size:9px}.search b{font-size:14px;font-weight:400}.notification{position:relative;color:#4c6d89;font-size:16px}.notification:after{content:"3";position:absolute;top:-5px;right:-7px;width:11px;height:11px;display:grid;place-items:center;color:#fff;background:#ff4c53;border-radius:50%;font-size:7px;font-weight:800}.admin-avatar{width:27px;height:27px;display:grid;place-items:center;border-radius:50%;color:#fff;background:var(--navy);font-size:10px;font-weight:800}.account b,.account small{display:block}.account b{font-size:10px}.account small{color:var(--muted);font-size:8px}.welcome{min-height:90px;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:space-between;gap:18px;padding:17px 20px;color:#fff;border-radius:10px;background:radial-gradient(circle at 66% 49%,rgba(97,210,232,.40),transparent 13%),radial-gradient(circle at 52% 6%,rgba(106,217,229,.23),transparent 22%),linear-gradient(110deg,#07506c,#0b6c86 63%,#087a7d);box-shadow:0 10px 24px rgba(9,68,95,.15)}.welcome:before{content:"";position:absolute;width:250px;height:250px;right:23%;bottom:-185px;border:24px solid rgba(163,238,246,.14);border-radius:50%}.welcome-content,.date-card{z-index:1}.eyebrow{color:#6be6da;font-size:8px;letter-spacing:.16em;font-weight:800;text-transform:uppercase}.welcome h1{margin:5px 0 4px;font-size:22px;letter-spacing:-.04em}.welcome p{margin:0;color:#c7e6ed;font-size:9px}.date-card{display:flex;align-items:center;gap:9px;padding-left:16px;border-left:1px solid rgba(255,255,255,.24);color:#c7e9ed;font-size:8px}.date-card i{width:30px;height:30px;display:grid;place-items:center;border-radius:7px;color:#d8fffb;background:rgba(107,235,216,.21);font-style:normal;font-size:16px}.date-card b{display:block;color:#fff;font-size:10px}.date-card small{display:block;margin-top:2px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:11px 0}.metric{min-width:0;min-height:79px;padding:12px 13px;border:1px solid #e4edf3;border-radius:10px;background:#fff;box-shadow:0 7px 18px rgba(20,65,94,.06)}.metric.mint{background:linear-gradient(120deg,#fff,#e9fffa)}.metric.blue{background:linear-gradient(120deg,#fff,#edf5ff)}.metric.orange{background:linear-gradient(120deg,#fff,#fff2ea)}.metric.purple{background:linear-gradient(120deg,#fff,#f5efff)}.metric-top{display:flex;justify-content:space-between;gap:6px;align-items:flex-start;color:#647f99;font-size:9px;font-weight:750}.metric-icon{width:27px;height:27px;display:grid;place-items:center;flex:none;border-radius:7px;background:#d9faf3;color:#09a78f;font-size:14px}.blue .metric-icon{background:#e4f0ff;color:#2f80e8}.orange .metric-icon{background:#ffe9dc;color:#f17841}.purple .metric-icon{background:#eee4ff;color:#8c61e7}.metric strong{display:block;margin:8px 0 2px;font-size:20px;letter-spacing:-.04em}.metric small{color:#13a58f;font-size:8px;font-weight:700}.blue small{color:#3079d6}.orange small{color:#ed7b41}.purple small{color:#775bd1}.content-grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(250px,.9fr);gap:11px}.panel{min-width:0;background:#fff;border:1px solid #e1ebf2;border-radius:10px;box-shadow:0 7px 18px rgba(20,65,94,.05)}.appointment-panel{padding:13px}.panel-heading{display:flex;align-items:center;justify-content:space-between;gap:10px}.panel-heading h2{margin:0;font-size:12px}.panel-heading h2:before{content:"▣";margin-right:7px;color:#13b9a3}.panel-heading a{color:#2586e7;font-size:9px;font-weight:800;text-decoration:none}.filters{display:flex;gap:6px;margin:11px 0 10px}.filters button{border:0;border-radius:5px;padding:5px 13px;color:#58718a;background:#f2f7fb;font-size:8px;font-weight:700}.filters button.active{color:#078f7b;background:#dffaf3}table{width:100%;border-collapse:collapse;text-align:left}th{padding:7px 9px;color:#7e96ad;background:#f4f8fb;font-size:7px;letter-spacing:.05em;text-transform:uppercase}td{padding:10px 9px;border-bottom:1px solid var(--line);font-size:9px}.person{display:flex;align-items:center;gap:7px;font-weight:750}.person i{width:22px;height:22px;display:grid;place-items:center;color:#078d7b;background:#e1f8f4;border-radius:50%;font-size:7px;font-style:normal}.badge{display:inline-block;padding:4px 7px;border-radius:99px;font-size:7px;font-weight:800}.confirmed{color:#078b78;background:#e4faf5}.pending{color:#c16d13;background:#fff3e2}.empty-state{height:135px;color:#7891a6;text-align:center;font-size:10px}.empty-state:before{content:"▦";display:block;margin:24px auto 8px;color:#c5d9e6;font-size:34px}.empty-state b{display:block;color:#688198;margin-bottom:4px}.tasks-panel{padding:13px}.tasks-panel .panel-heading h2:before{content:"✓"}.task{display:flex;gap:9px;padding:9px 0;border-bottom:1px solid var(--line)}.task:last-child{border-bottom:0}.task-check{width:16px;height:16px;flex:none;margin-top:1px;border:1.5px solid #c4d4e0;border-radius:4px}.task-check.done{position:relative;border-color:#17c1a9;background:#17c1a9}.task-check.done:after{content:"✓";position:absolute;top:-3px;left:2px;color:#fff;font-size:13px}.task b{display:block;font-size:9px}.task span{display:block;margin-top:2px;color:var(--muted);font-size:8px}.quick-actions{margin-top:11px;padding:12px}.quick-actions h3{margin:0 0 9px;font-size:10px}.quick-actions h3:before{content:"ϟ";margin-right:7px;color:#147ee3}.quick-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.quick-grid a{min-height:50px;padding:8px 4px;color:#57728b;text-align:center;text-decoration:none;border-radius:6px;background:#eefbf8;font-size:7px;font-weight:750}.quick-grid a:nth-child(2){background:#edf5ff}.quick-grid a:nth-child(3){background:#f6efff}.quick-grid a:nth-child(4){background:#fff3eb}.quick-grid i{display:block;margin-bottom:4px;color:#08a990;font-style:normal;font-size:15px}.quick-grid a:nth-child(2) i{color:#277de0}.quick-grid a:nth-child(3) i{color:#8d61e6}.quick-grid a:nth-child(4) i{color:#ee7540}@media(max-width:1000px){.admin{grid-template-columns:64px minmax(0,1fr)}.sidebar{padding:13px 9px}.brand{justify-content:center;padding-bottom:20px}.brand-copy,.section-label,.nav span,.upgrade div{display:none}.nav a{justify-content:center;padding:9px}.upgrade{justify-content:center;padding:8px}.utility{padding:0 15px}.main{padding:0 13px 22px}.utility{margin-left:-13px;margin-right:-13px}.date-card{display:none}.content-grid{grid-template-columns:1fr}.quick-actions{display:none}}@media(max-width:680px){.admin{display:block}.sidebar{display:none}.main{padding:0 11px 20px}.utility{margin:0 -11px 9px;height:44px}.search{width:52vw}.account{display:none}.welcome{min-height:100px;padding:16px}.welcome h1{font-size:20px}.metrics{grid-template-columns:repeat(2,1fr)}.content-grid{gap:9px}.appointment-panel{overflow-x:auto}.appointment-panel table{min-width:470px}.tasks-panel{padding:12px}}
